import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Typography } from 'antd';

import PlusIcon from 'assets/images/icons/plus.svg?react';
import noNameImg from 'assets/images/no_name.webp';
import { MOCK_ICollection } from 'shared/consts/MOCK_FOR_CATALOG';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, NoResults } from 'shared/ui';

import styles from './CollectionList.module.scss';

interface ICollectionListProps extends HTMLAttributes<HTMLDivElement> {
	data: MOCK_ICollection[];
	isFetching: boolean;
	isLoading: boolean;
}

export const CollectionList: FC<ICollectionListProps> = ({ data, isLoading, ...props }) => {
	const { t } = useTranslation();

	return (
		<>
			{!isLoading && !data?.length ? (
				<NoResults
					text={t('Нет коллекций')}
					subtext={t('Вы пока не добавили еще ни одного поста и не создали ни одной коллекции')}
					goTo={
						<ButtonStyleLink
							className={styles.collectionList__btnAdd}
							to={`/${EMainRoutes.COLLECTIONS}/${EMainRoutes.CREATE}`}
							icon={<PlusIcon />}
							type="primary"
							iconPosition="end"
							block
							size="large">
							{t('Новая коллекция')}
						</ButtonStyleLink>
					}
				/>
			) : (
				<Flex {...props} vertical gap={12}>
					<Flex vertical gap={4}>
						<ButtonStyleLink
							className={styles.collectionList__btnAdd}
							to={`/${EMainRoutes.COLLECTIONS}/${EMainRoutes.CREATE}`}
							icon={<PlusIcon />}
							iconPosition="end">
							{t('Новая коллекция')}
						</ButtonStyleLink>
						{data.map((collection) => (
							<ButtonStyleLink
								className={styles.collectionList__btn}
								key={collection.id}
								icon={<img src={noNameImg} alt={''} width={38} height={38} />}
								iconPosition="end"
								to={`/${EMainRoutes.COLLECTIONS}/${collection.id}`}>
								<Flex vertical>
									<Typography.Text strong>{collection.name}</Typography.Text>
									<Typography.Text type="secondary">
										{t('Постов')}: {collection.items.length}
									</Typography.Text>
								</Flex>
							</ButtonStyleLink>
						))}
					</Flex>
				</Flex>
			)}
		</>
	);
};
